contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take amount to deposit and amount to collect
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // Ensure MinSum is set to 0 (via c.SetMinSum) before initialization so we can collect conditionally.
        // SetMinSum can only be called before c.Initialized(). We call it here.
        // This may revert if already initialized; on fresh c it's allowed.
        c.SetMinSum(0);

        // Record balances before interactions
        uint beforeCallerRecorded = c.balances(address(this));
        uint beforeCbalance = address(c).balance;

        // Deposit depositAmt into c as this contract (msg.sender == address(this) for c calls)
        // Only perform deposit if depositAmt > 0 to avoid unnecessary call, but Deposit can accept 0 too.
        if (depositAmt > 0) {
            c.Deposit{value: depositAmt}();
        } else {
            // still call Deposit with 0 to exercise path
            c.Deposit{value: 0}();
        }

        // After deposit, record recorded balance and contract balance
        uint afterDepositRecorded = c.balances(address(this));
        uint afterDepositCbalance = address(c).balance;

        // The recorded balance must have increased by exactly depositAmt
        // (use require so test aborts early if weird environment; assert must be single at end)
        require(afterDepositRecorded == beforeCallerRecorded + depositAmt, "deposit did not increase recorded balance correctly");
        require(afterDepositCbalance == beforeCbalance + depositAmt, "deposit did not change contract balance correctly");

        // Now attempt to Collect collectAmt. Catch whether it reverts.
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read post-state
        uint finalRecorded = c.balances(address(this));
        uint finalCbalance = address(c).balance;

        // General invariant asserted for all inputs: if Collect succeeded (didn't revert) then
        // the recorded balance decreased by collectAmt and the contract's Ether balance decreased by collectAmt.
        // If Collect reverted, no requirements are made here (reverts imply preconditions failed).
        assert(collectReverted || (finalRecorded == afterDepositRecorded - collectAmt && finalCbalance == afterDepositCbalance - collectAmt));
    }

    // Allow receiving Ether if ever needed
    receive() external payable {}
}

