contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: set MinSum to 0, ensure LogFile is set to c.Log (already possible), deposit some ETH, then attempt Collect.
    // Inputs: amount to deposit and amount to collect. The function is payable only to fund this test contract for the deposit/collect flow.
    function run(uint depositAmt, uint collectAmt, address payable logAddr) public payable {
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // Initialize mutable configuration before Initialized is called on c
        // Attempt to set MinSum to 0 to allow Collect when balance >= collectAmt
        // These calls may revert if c has been initialized; the fresh c deployed by checker is uninitialized so they should succeed.
        c.SetMinSum(0);
        c.SetLogFile(logAddr);

        // Record balances before deposit
        uint beforeStored = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // Deposit funds to c from this contract
        c.Deposit{value: depositAmt}();

        // Now try Collect and capture whether it reverted
        bool didRevert;
        try c.Collect(collectAmt) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read after-values available via public getters
        uint afterStored = c.balances(address(this));
        uint afterContractEth = address(c).balance;

        // Inspect LogFile's last message via its public History getter: History(uint) returns tuple, but we can read Last by index length-1
        // First get length by calling History(uint) with a large index may revert; instead we rely on Log.AddMessage being called only on success path.
        // We can read the last pushed message via Log.History(index). The LogFile contract has History as public Message[] so History(i) exists.
        // To avoid index out-of-bounds when no messages were pushed, we will only assert the log contents when Collect succeeded.

        // The invariant to assert: if Collect did not revert, then
        // 1) the stored balance decreased by exactly collectAmt
        // 2) the contract ETH decreased by exactly collectAmt
        // 3) the last log entry's Data == "Collect" and Val == collectAmt
        // We can read the last History entry index as History.length-1 by probing increasing indices until we find the last one is not possible in pure solidity here.
        // However, the LogFile has public array History and its getter signature is (uint)->(address,string,uint,uint). We can attempt to read History(beforeIndex) where beforeIndex = beforeStored + 0; that is not helpful.
        // Alternative approach: call LogFile.LastMsg via its implicit getter LastMsg() does not exist as LastMsg is not public; but History is public so we can access the element at index (afterStored == beforeStored - collectAmt) position is unknown.
        // Simpler and still strong rule: if Collect succeeded then both stored and ETH balances decreased by collectAmt and collectAmt>0 implies last call emitted a log entry with Val equal to collectAmt. We can verify existence by scanning a reasonable index range: since only this test interacted with c, the number of log entries cannot exceed (1 + number of calls we made). We made at most 2 AddMessage calls (Deposit and Collect). So the last 2 indices are at most 1 and 0. We'll read both if they exist.

        // Try to read two possible recent history entries from the Log contract set earlier.
        LogFile lf = LogFile(logAddr);
        // Determine history length by attempting to read index 1 then 0; if index 1 reverts then length <=1.
        bool idx1_ok = true;
        address h1_sender;
        string memory h1_data;
        uint h1_val;
        uint h1_time;
        try lf.History(1) returns (address a, string memory d, uint v, uint t) {
            h1_sender = a; h1_data = d; h1_val = v; h1_time = t;
        } catch {
            idx1_ok = false;
        }
        bool idx0_ok = true;
        address h0_sender;
        string memory h0_data;
        uint h0_val;
        uint h0_time;
        try lf.History(0) returns (address a0, string memory d0, uint v0, uint t0) {
            h0_sender = a0; h0_data = d0; h0_val = v0; h0_time = t0;
        } catch {
            idx0_ok = false;
        }

        // Build condition for successful Collect: both stored and ETH decreased exactly by collectAmt and collect did not revert
        bool balances_decreased = (beforeStored >= afterStored) && (beforeStored - afterStored == (didRevert ? 0 : collectAmt));
        bool eth_decreased = (beforeContractEth >= afterContractEth) && (beforeContractEth - afterContractEth == (didRevert ? 0 : collectAmt));

        // If Collect succeeded, then one of the last two history entries must record the Collect with Val==collectAmt and Data=="Collect" from this address.
        bool collect_logged = false;
        if (!didRevert) {
            if (idx1_ok) {
                // compare bytes of strings by keccak
                if (h1_sender == address(this) && h1_val == collectAmt && keccak256(bytes(h1_data)) == keccak256(bytes("Collect"))) collect_logged = true;
            }
            if (!collect_logged && idx0_ok) {
                if (h0_sender == address(this) && h0_val == collectAmt && keccak256(bytes(h0_data)) == keccak256(bytes("Collect"))) collect_logged = true;
            }
        }

        // Final general assert: whenever Collect did not revert, stored and ETH decreased exactly by collectAmt and a Collect log entry with Val==collectAmt by this contract exists in the recent history.
        assert(didRevert || (balances_decreased && eth_decreased && collect_logged));
    }

    // Allow receiving ETH to fund deposits
    receive() external payable {}
 }

